  ('AXI-VIS-PLA-AXI-001', 'AXIS-PDF-OFFER-42', 'Travel', 'SaffronStays', 'Instant Discount', 'One Time', 'Active', 'All Days', 'Per Transaction', 'Cardholder', 'N/A', 'N/A', '20000', 'N/A', '2026-04-01', '2027-03-31', 'https://brands.adneto.in/saffronstay', 'Card-specific', 'AXIS-AXIS-BANK-PRIDE-PLATINUM-CREDIT-CARD', '36 Months', 'ADNETO20 | ADNETO15 | ADNETO10', 'Other', 'N/A', '{"rp_pointType":"Cash/Discount","rp_calc":"Offer 1: 1. Book a minimum of 4 nights at SaffronStays and avail a 15% discount up to Rs.20,000 2. Use Coupon code: ADNETO20 Offer 2: 1. Book a minimum of 3 nights at SaffronStays and avail a 15% discount up to Rs 15,000 2. Use Coupon code: ADNETO15 Offer 3: 1. Book a minimum of 2 nights at SaffronStays and avail a 10% discount 2. Use Coupon code: ADNETO10 3. This offer is valid only on reservations made through SaffronStays 4. This offer is valid on select villas and exclusive to Adneto partners only 5. This offer is valid on accommodation only 6. All meals (Breakfast / Lunch / Hi Tea / Dinner) shall be charged on actuals as per applicable rates on the website 7. This offer cannot be clubbed with any other existing discounts and promotions or reward points Steps to avail: 1. Click on https://brands.adneto.in/saffronstay 2. Select the hotel/ Villa of your choice, apply the coupon codes 3. Pay with your Axis Bank Credit or Debit Cards Exclusions: • Offer is not valid on Axis Bank RuPay Credit Card transactions done Via UPI • Offer not valid on Corporate or Commercial Credit cards."}'::jsonb, 'Cash/Discount', 'Offer 1: 1. Book a minimum of 4 nights at SaffronStays and avail a 15% discount up to Rs.20,000 2. Use Coupon code: ADNETO20 Offer 2: 1. Book a minimum of 3 nights at SaffronStays and avail a 15% discount up to Rs 15,000 2. Use Coupon code: ADNETO15 Offer 3: 1. Book a minimum of 2 nights at SaffronStays and avail a 10% discount 2. Use Coupon code: ADNETO10 3. This offer is valid only on reservations made through SaffronStays 4. This offer is valid on select villas and exclusive to Adneto partners only 5. This offer is valid on accommodation only 6. All meals (Breakfast / Lunch / Hi Tea / Dinner) shall be charged on actuals as per applicable rates on the website 7. This offer cannot be clubbed with any other existing discounts and promotions or reward points Steps to avail: 1. Click on https://brands.adneto.in/saffronstay 2. Select the hotel/ Villa of your choice, apply the coupon codes 3. Pay with your Axis Bank Credit or Debit Cards Exclusions: • Offer is not valid on Axis Bank RuPay Credit Card transactions done Via UPI • Offer not valid on Corporate or Commercial Credit cards.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
